def paginate(query, page=1, per_page=20):
    offset = (page - 1) * per_page
    return f"SELECT * FROM {query} LIMIT {per_page} OFFSET {offset}"

def build_log(level, *msgs, **meta):
    return {"level": level, "message": " ".join(msgs), "metadata": meta}

print(paginate("users"))
print(paginate("users", page=3, per_page=50))
print(build_log("INFO", "Kakade login", user_id=42))

